function applyPatchOps(doc, ops) {
  for (const { path, value } of ops) {
    const keys = path.split('/').filter(Boolean);
    if (keys.some((k) => k === '__proto__' || k === 'constructor' || k === 'prototype')) continue;
    const last = keys.pop();
    const target = keys.reduce((o, k) => (o[k] = o[k] || {}), doc);
    target[last] = value;
  }
  return doc;
}

