app.get('/theme', (req, res) => {
  const rules = [];
  for (const [k, v] of Object.entries(JSON.parse(String(req.query.css || '{}')))) {
    if (PROPERTIES.has(k) && /^[#\w(),.\s%-]+$/.test(String(v))) rules.push(`${k}: ${v}`);
  }
  res.type('text/css').send(`body { ${rules.join(';')} }`);
});
